mapper.select:
WITH RECURSIVE tenant_hidden_menu(id) AS ( SELECT config.menu_permission_id FROM public.iam_tenant_menu_config config WHERE config.tenant_id=#{tenantId} AND config.hidden=true AND config.is_deleted=false UNION SELECT child.id FROM public.iam_permission_resource child JOIN tenant_hidden_menu parent ON child.parent_id=parent.id WHERE child.is_deleted=false ) SELECT permission.id AS permission_id, permission.parent_id, permission.permission_code, permission.name, permission.route_path, permission.feature_code, CASE WHEN permission.feature_code IS NULL THEN true ELSE COALESCE(feature.enabled, false) END AS feature_enabled, false AS tenant_hidden, config.version AS tenant_version, COALESCE(preference.hidden, false) AS personally_hidden, preference.version AS preference_version, permission.sort_order FROM public.iam_permission_resource permission JOIN public.iam_tenant_menu_config config ON config.tenant_id=#{tenantId} AND config.menu_permission_id=permission.id AND config.is_deleted=false LEFT JOIN public.iam_tenant_feature feature ON feature.tenant_id=config.tenant_id AND feature.feature_code=permission.feature_code AND feature.is_deleted=false LEFT JOIN public.iam_account_menu_preference preference ON preference.tenant_id=config.tenant_id AND preference.account_id=#{accountId} AND preference.menu_permission_id=permission.id AND preference.is_deleted=false WHERE permission.app_code='TENANT_ADMIN' AND permission.resource_type IN ('DIRECTORY','MENU') AND permission.publish_status='PUBLISHED' AND permission.is_deleted=false AND permission.permission_code IN
#{permissionCode}
AND permission.id NOT IN (SELECT id FROM tenant_hidden_menu) AND (permission.feature_code IS NULL OR COALESCE(feature.enabled, false)=true) ORDER BY permission.sort_order, permission.id

WITH RECURSIVE hidden_menu(id) AS ( SELECT config.menu_permission_id FROM public.iam_tenant_menu_config config WHERE config.tenant_id=#{tenantId} AND config.hidden=true AND config.is_deleted=false UNION SELECT preference.menu_permission_id FROM public.iam_account_menu_preference preference WHERE preference.tenant_id=#{tenantId} AND preference.account_id=#{accountId} AND preference.hidden=true AND preference.is_deleted=false UNION SELECT child.id FROM public.iam_permission_resource child JOIN hidden_menu parent ON child.parent_id=parent.id WHERE child.is_deleted=false ) SELECT permission.permission_code FROM public.iam_permission_resource permission WHERE permission.id IN (SELECT id FROM hidden_menu) AND permission.permission_code IN
#{permissionCode}
ORDER BY permission.permission_code
